# 真指令求签并推进 day/night/settle；只补测试数据，不替换处理器。
# 验证未来天气和日循环实际变化下，预言仍发出或同征兆替身。
extends SceneTree
const T = preload("res://scripts/tests/cards/lib/card_t.gd")
const F = preload("res://scripts/tests/cards/G05/fixture.gd")
const S = preload("res://scripts/cards/fate/fate_support.gd")
func _initialize() -> void:
	var t := T.new(self, "G05_true_lot_loop")
	var promised := 0
	var delivered := 0
	for seed in range(20):
		var eng := CardEngine.new()
		t.ok(bool(eng.new_game({"seed": seed, "only_examples": true, "save_dir": t.user_dir()}).get("ok")), "true new game")
		eng.ctx.db = F.db()
		t.ok(bool(eng.send(&"wheel.spin", {"wheel": "wh.month", "uid": ""}).get("ok")), "monthly spin")
		t.ok(bool(eng.send(&"month.begin", {}).get("ok")), "month begin")
		t.ok(bool(eng.send(&"day.begin", {}).get("ok")), "first day")
		var uid := F.fortune_uid(eng.ctx)
		for lot in range(3):
			t.ok(bool(eng.send(&"fortune.lot", {"uid": uid}).get("ok")), "real lot command")
		var pins: Dictionary = eng.ctx.state.ns("fate").get("pins", {}).duplicate(true)
		for day in range(2, 5):
			t.ok(bool(eng.send(&"day.end", {"confirm_gold_leave": true}).get("ok")), "real day end")
			var offers: Array = eng.view().get("night_offers", [])
			var night := "nt.tidy" if offers.has("nt.tidy") else (str(offers[0]) if not offers.is_empty() else "")
			var choices: Array = eng.ctx.db.def(night).get("choices", [])
			var choice := str(choices[0]["id"]) if not choices.is_empty() else ""
			t.ok(bool(eng.send(&"night.choose", {"def": night, "choice": choice}).get("ok")), "real night choose")
			t.ok(bool(eng.send(&"settle.next", {}).get("ok")), "real settle next")
			t.ok(bool(eng.send(&"day.begin", {}).get("ok")), "real future day begin")
			t.eq(eng.ctx.abs_day(), day, "real date advanced")
			var definitions: Array = []
			for card in eng.view().get("hand", []):
				definitions.append(str(card["def"]))
			for def_id in pins.get(str(day), []):
				promised += 1
				var found := definitions.has(str(def_id))
				if not found:
					var old := eng.ctx.db.def(str(def_id))
					for actual in definitions:
						var candidate := eng.ctx.db.def(str(actual))
						if str(candidate.get("type", "")) == str(old.get("type", "")) and S.intersects(S.omens(old), S.omens(candidate)):
							found = true
				if found:
					delivered += 1
				t.ok(found, "true loop promise or same-omen substitute delivered")
		t.eq(t.find_floats(eng.ctx.state.data), PackedStringArray(), "real loop state integers")
	print("G05 TRUE LOT LOOP seeds=0..19 lots=60 promised=%d delivered=%d rate=100%% no_handler_doubles=true" % [promised, delivered])
	t.eq(delivered, promised, "all actual loop predictions fulfilled")
	t.ok(promised > 0, "real loop promises observed")
	t.finish()
